function adapt(input, solve, kit) {
  const [n] = input, values = [];
  const gen = solve(n);
  if (!gen || typeof gen.next !== 'function') throw new Error('factorial must return a generator object.');
  kit.trace(`factorial(${n}) creates the generator`);
  for (;;) {
    const step = gen.next();
    if (!step || typeof step !== 'object') throw new Error('next() must return an object with value and done.');
    if (step.done) {
      kit.trace('gen.next() reports done');
      break;
    }
    if (typeof step.value !== 'number') throw new Error('Each value the generator hands out must be a number.');
    kit.trace(`gen.next() yields ${step.value}`);
    values.push(step.value);
    if (values.length > 30) throw new Error('The generator handed out more than 30 values; it should finish after n!.');
  }
  return values;
}

