function* factorial(n) {
  // Recompute every factorial from scratch; 0 still produces the single value 0! = 1.
  const last = Math.max(n, 1);
  for (let k = 1; k <= last; k++) {
    let value = 1;
    for (let factor = 2; factor <= k; factor++) value *= factor;
    yield value;
  }
}

